/** The rooms of the device socket, with the names of their messages */
export interface SocketRooms {
  /** Live graph values, valves and routines, used by the graph of the HDM web app */
  graph:
    | "graph:graph"
    | "graph:io"
    | "graph:routine"
    | "graph:restart"
    | "graph:dynamic-graph";
  /** Settings the device reports, e.g. the time left of filth removal */
  "device-state": "device-state:setting-value";
  /** Whether the device is connected to HDM */
  "device-status": "device-status:online" | "device-status:offline";
  /** The status log */
  maintenance: "maintenance:status-log-entry";
  /** The priorities of the outlets */
  "output-priorities": "output-priorities:setting-value";
  /** Device settings, for the settings page of the HDM web app */
  settings: "settings:setting-value";
  /** State machines of the device, e.g. maintenance procedures */
  fsm: "fsm:transition";
  /** Firmware uploads */
  "device-progress": "device-progress:progress";
  /** The device log */
  logging: "logging:entry";
  /** The device dashboard of the HDM web app. Needs permissions owners don't have. */
  dashboard:
    | "dashboard:graph-data"
    | "dashboard:io-data"
    | "dashboard:routine"
    | "dashboard:setting-value"
    | "dashboard:time-left-recycling"
    | "dashboard:latest-device-task"
    | "dashboard:recycle-statistics"
    | "dashboard:firmware-upload-data";
  /** Video calls of the HDM web app. Every HDM web app that shows the device emits `in-call`, `out-call` and `refresh-call` on the device socket, which the server relays to the room, `refresh-call` without the id. */
  communication:
    | "communication:in-call"
    | "communication:out-call"
    | "communication:refresh-call";
}

export type SocketRoom = keyof SocketRooms;

/** A message of the given rooms, with its name and payload */
export type SocketMessage<R extends SocketRoom = SocketRoom> = {
  [N in SocketRooms[R]]: { name: N; payload: SocketMessages[N] };
}[SocketRooms[R]];
